const config = $input.first().json;
const cities = [
  { city: 'Nanjing', latitude: 32.0603, longitude: 118.7969, timezone: 'Asia/Shanghai' },
  { city: 'Wuhu', latitude: 31.3525, longitude: 118.4331, timezone: 'Asia/Shanghai' },
];
return cities.map((city) => ({ json: { ...config, ...city } }));

const cities = $items('City List');
const responses = $input.all();
return responses.map((item, index) => ({
  json: {
    city: cities[index]?.json?.city || `City ${index + 1}`,
    latitude: cities[index]?.json?.latitude,
    longitude: cities[index]?.json?.longitude,
    timezone: cities[index]?.json?.timezone || item.json.timezone,
    recipientEmail: cities[index]?.json?.recipientEmail || '',
    fromEmail: cities[index]?.json?.fromEmail || '',
    useAi: Boolean(cities[index]?.json?.useAi),
    weather: item.json,
  },
}));

const weatherText = (code) => {
  if (code === 0) return 'Clear';
  if ([1, 2].includes(code)) return 'Mostly clear or partly cloudy';
  if (code === 3) return 'Overcast';
  if ([45, 48].includes(code)) return 'Fog';
  if ([51, 53, 55, 56, 57].includes(code)) return 'Drizzle';
  if ([61, 63, 65, 66, 67, 80, 81, 82].includes(code)) return 'Rain';
  if ([71, 73, 75, 77, 85, 86].includes(code)) return 'Snow';
  if ([95, 96, 99].includes(code)) return 'Thunderstorms';
  return 'Unknown conditions';
};
const round = (value) => Number.isFinite(Number(value)) ? Math.round(Number(value)) : null;
const items = $input.all();
const sections = [];
const cards = [];
const problems = [];
for (const item of items) {
  const { city, weather, timezone } = item.json;
  if (!timezone) throw new Error(`Missing timezone for ${city}`);
  const daily = weather?.daily;
  const hourly = weather?.hourly;
  const date = daily?.time?.[0] || new Date().toLocaleDateString('en-CA', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' });
  if (!daily?.time?.length || !hourly?.time?.length) {
    problems.push(city);
    sections.push(`[${city}] ${date} (${timezone}) Weather data is temporarily unavailable. Please check again later.`);
    cards.push({ city, available: false, date, timezone });
    continue;
  }
  const max = round(daily.temperature_2m_max?.[0]);
  const min = round(daily.temperature_2m_min?.[0]);
  const apparentMax = round(daily.apparent_temperature_max?.[0]);
  const rainChance = round(daily.precipitation_probability_max?.[0]) ?? 0;
  const rain = Number(daily.precipitation_sum?.[0] ?? 0);
  const wind = round(daily.wind_speed_10m_max?.[0]) ?? 0;
  const gust = round(daily.wind_gusts_10m_max?.[0]) ?? 0;
  const uv = Number(daily.uv_index_max?.[0] ?? 0);
  const condition = weatherText(daily.weather_code?.[0]);
  const targetHours = ['09:00', '12:00', '15:00', '18:00', '21:00'];
  const hourlyRows = targetHours.map((clock) => {
    const index = hourly.time.indexOf(`${date}T${clock}`);
    if (index < 0) return `${clock} No data available`;
    const temperature = round(hourly.temperature_2m?.[index]);
    const feels = round(hourly.apparent_temperature?.[index]);
    const probability = round(hourly.precipitation_probability?.[index]) ?? 0;
    return `${clock} ${weatherText(hourly.weather_code?.[index])} ${temperature}°C (feels like ${feels}°C), precipitation ${probability}%`;
  });
  const advice = [];
  if (rainChance >= 50 || rain >= 1) advice.push('Carry an umbrella and watch for slippery surfaces');
  if (max !== null && max >= 35) advice.push('Stay hydrated and limit outdoor activity in the afternoon heat');
  else if (max !== null && max >= 30) advice.push('Expect a warm afternoon; stay hydrated and use sun protection');
  if (min !== null && min <= 10) advice.push('Mornings and evenings may be cool; add a layer');
  if (gust >= 50 || wind >= 35) advice.push('Strong winds: watch for falling objects and secure outdoor items');
  if (uv >= 6) advice.push('High UV levels: use sun protection outdoors');
  if (!advice.length) advice.push('Generally settled weather; proceed with normal daily plans');
  sections.push([
    `[${city}] ${date} (${timezone}), ${condition}, ${min}–${max}°C, maximum feels-like ${apparentMax}°C`,
    `Precipitation probability ${rainChance}%, total ${rain.toFixed(1)} mm; maximum wind ${wind} km/h, gusts ${gust} km/h; UV ${uv.toFixed(1)}`,
    ...hourlyRows.map((row) => `- ${row}`),
    `Advice: ${advice.join('; ')}.`,
  ].join('\n'));
  cards.push({ city, available: true, date, timezone, condition, min, max, apparentMax, rainChance, rain, wind, gust, uv, hourlyRows, advice });
}
const date = [...new Set(cards.map((card) => card.date))].join(' / ');
const ruleSummary = `Good morning. Here is the ${date} weather brief for Nanjing and Wuhu. All forecast times are local to each city.\n\n${sections.join('\n\n')}\n\nData source: Open-Meteo.`;
const aiPrompt = `You are a precise, restrained English-language weather editor. Write an English opening summary for a morning email using the weather information below. Requirements: 1) Do not invent data; 2) Describe shared trends before differences between the cities; 3) Highlight actionable rain, heat, and wind information; 4) Use 60 to 100 words; 5) Return only the prose, without a heading.\n\n${ruleSummary}`;
return [{ json: { date, cards, problems, ruleSummary, aiPrompt, recipientEmail: items[0]?.json?.recipientEmail || '', fromEmail: items[0]?.json?.fromEmail || '', useAi: Boolean(items[0]?.json?.useAi) } }];

const base = $items('Compose Dual-City Brief')[0].json;
const incoming = $input.first()?.json || {};
const aiText = typeof incoming.text === 'string' ? incoming.text.trim() : (typeof incoming.output === 'string' ? incoming.output.trim() : '');
const opening = aiText || 'Here are the local forecasts and travel tips for both cities. Plan around precipitation, wind, and feels-like temperatures.';
const escapeHtml = (value) => String(value).replace(/[&<>]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[character]);
const cardHtml = base.cards.map((card) => {
  if (!card.available) return `<section style="padding:16px;margin:12px 0;border:1px solid #f0c36d;border-radius:12px;background:#fff8e1"><h2 style="margin:0 0 8px">${escapeHtml(card.city)}</h2><p>${escapeHtml(card.date)} · ${escapeHtml(card.timezone)}</p><p>Weather data is temporarily unavailable. Please check again later.</p></section>`;
  const hours = card.hourlyRows.map((row) => `<li style="margin:5px 0">${escapeHtml(row)}</li>`).join('');
  return `<section style="padding:18px;margin:14px 0;border:1px solid #dbe7f3;border-radius:12px;background:#f8fbff"><h2 style="margin:0 0 10px;color:#174a7c">${escapeHtml(card.city)} · ${escapeHtml(card.condition)}</h2><p>${escapeHtml(card.date)} · ${escapeHtml(card.timezone)}</p><p style="font-size:20px;margin:8px 0"><strong>${card.min}–${card.max}°C</strong> <span style="font-size:14px;color:#52606d">Maximum feels-like ${card.apparentMax}°C</span></p><p>Precipitation probability ${card.rainChance}% · Total ${card.rain.toFixed(1)} mm · Maximum wind ${card.wind} km/h · Gusts ${card.gust} km/h · UV ${card.uv.toFixed(1)}</p><ul style="padding-left:22px">${hours}</ul><p style="margin-bottom:0;color:#8a4b08"><strong>Advice:</strong> ${escapeHtml(card.advice.join('; '))}.</p></section>`;
}).join('');
const warning = base.problems.length ? `<p style="padding:10px;background:#fff3cd;border-radius:8px">Notice: weather data could not be retrieved for ${escapeHtml(base.problems.join(', '))}.</p>` : '';
const html = `<div style="max-width:720px;margin:auto;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#243447;line-height:1.65"><h1 style="color:#0b5f8a">Nanjing · Wuhu Daily Weather Brief</h1><p style="color:#52606d">${escapeHtml(base.date)} · Times are local to each city</p><p style="font-size:16px">${escapeHtml(opening)}</p>${warning}${cardHtml}<p style="margin-top:24px;font-size:12px;color:#7b8794">Weather data: Open-Meteo. Forecasts are uncertain; follow official local weather alerts. ${aiText ? 'The opening summary was generated with AI assistance.' : 'This brief uses the deterministic rule summary.'}</p></div>`;
return [{ json: { toEmail: base.recipientEmail, fromEmail: base.fromEmail, subject: `Nanjing and Wuhu Weather Brief | ${base.date}`, html, usedAi: Boolean(aiText) } }];
